-- +goose Up
-- +goose StatementBegin
-- Question bank for the tournament "Королевская битва" (grades 5-6), transcribed from
-- Mat_Turnir_5-6_Svodny_Sbornik_Zadanij-v2.docx: 20 + 15 + 10 questions plus a
-- 3-question reserve pool (round 4) for tie-breaks.
-- The event was created manually via the UI, so it is looked up by name; on a
-- database without this event the migration is a no-op.
INSERT INTO quiz_questions (event_id, round, question_number, text, answer, explanation, criteria)
SELECT e.id, v.round, v.question_number, v.text, v.answer, v.explanation, v.criteria
FROM events e
CROSS JOIN (VALUES
    (1, 1, 'За одну минуту от бревна отпиливается кусок длиной 2 метра. Сколько времени требуется, чтобы распилить на такие куски бревно длиной 10 метров?', '4 минуты.', 'Бревно длиной 10 м делится на 5 кусков по 2 м; для этого нужно сделать 4 распила.', ''),
    (1, 2, 'Три сестры Анна, Ева и Лиза одинаково быстро и хорошо умеют навести порядок в квартире. Если любые две из этих девочек будут работать вместе, то справятся с уборкой за час. Сколько времени девочки потратят на уборку, если будут работать все трое вместе?', '40 минут.', 'Две девочки тратят 60 × 2 = 120 человеко-минут; втроем справятся за 120 : 3 = 40 минут.', ''),
    (1, 3, 'Когда в школе объявили день вежливости, каждый мальчик из 5А класса поздоровался за руку с каждой девочкой из своего класса. Всего при этом было 77 рукопожатий. Сколько учеников может быть в 5А классе?', '18 учеников.', 'Число 77 раскладывается как 7 × 11 (мальчики и девочки), всего 7 + 11 = 18 учеников.', ''),
    (1, 4, 'Шутка. На столе в ряд стоят шесть стаканов, первые три с напитком, а потом три пустых. Требуется расположить их так, чтобы стаканы с напитком и пустые стаканы чередовались через один, причем разрешается брать в руки только один стакан.', 'Взять второй стакан и перелить его содержимое в пятый стакан; второй стакан поставить на место.', '', ''),
    (1, 5, 'В одной многодетной семье у каждого из пяти сыновей по три сестры. Сколько всего детей в этой семье?', '8 детей.', '5 сыновей и 3 общие сестры.', ''),
    (1, 6, 'У сестер Юли и Тони было три платка: один розовый и два голубых. Увидев на Юле один из этих платков, Тоня поняла, что она может надеть только голубой платок. Какой платок был на Юле?', 'На Юле был розовый платок.', 'Розовый платок всего один; раз Тоня увидела, что выбора цвета не осталось, на Юле именно он.', ''),
    (1, 7, 'Вите необходимо пройти в 4 раза больше ступенек, чем Руслану. Руслан живет на третьем этаже. На каком этаже живет Витя?', 'На девятом этаже.', 'До 3-го этажа нужно пройти 2 пролета; 2 × 4 = 8 пролетов; 1 + 8 = 9-й этаж.', ''),
    (1, 8, 'У Коли и Маши было поровну тетрадей. Коля из своих тетрадей дал две Маше. На сколько больше тетрадей стало у Маши, чем у Коли?', 'На 4.', 'У Коли стало на 2 меньше, у Маши — на 2 больше; разница 4 тетради.', ''),
    (1, 9, 'Два землекопа за 2 часа работы выкопают 2 м канавы. Сколько нужно землекопов, чтобы они за 100 часов работы выкопали 100 м такой же канавы?', '2 землекопа.', 'Два землекопа выкапывают по 1 м канавы за каждый час работы.', ''),
    (1, 10, 'Муравьишка ехал верхом на Гусенице 24 минуты, а потом пересел на Жука и проехал на нем в 4 раза больший путь. Сколько минут он ехал на Жуке, если Жук передвигается в 8 раз быстрее Гусеницы?', '12 минут.', 'Путь увеличился в 4 раза, а скорость — в 8 раз: 24 × 4 : 8 = 12 минут.', ''),
    (1, 11, 'Два ковша воды — это половина ведерка, а три чашки — это половина ковша. Сколько чашек в двух ведерках?', '48 чашек.', 'В 1 ковше 6 чашек; в 1 ведерке 4 ковша = 24 чашки; в 2 ведерках — 48 чашек.', ''),
    (1, 12, 'Сколько потребуется времени, чтобы поезд, длина которого 1 км, идущий со скоростью 60 км в час, прошел тоннель длиной в 1 км?', '2 минуты.', 'От входа локомотива до выхода последнего вагона поезд проходит 1 + 1 = 2 км.', ''),
    (1, 13, 'Один кирпич весит 1 килограмм и еще полкирпича. Сколько весит один кирпич?', '2 кг.', 'Полкирпича весит 1 кг, следовательно, целый кирпич весит 2 кг.', ''),
    (1, 14, 'В жаркий день 6 косцов выпили бочонок кваса за 8 часов. Нужно узнать, сколько косцов за 4 часа выпьют такой же бочонок кваса.', '12 косцов.', 'Время уменьшилось в 2 раза — число косцов должно увеличиться в 2 раза.', ''),
    (1, 15, 'Трое играли в шашки. Всего сыграли 3 партии. Сколько партий сыграл каждый?', '2 партии.', 'Каждый сыграл по одной партии с двумя другими участниками.', ''),
    (1, 16, 'Какой цифрой оканчивается произведение:
в) 11 · 12 · 13 · 14 · 15 · 16 · 17 · 18?', '0.', 'В произведении есть число 15 (оканчивается на 5) и четные числа; 5 × 2 дает 0 на конце.', ''),
    (1, 17, 'Сколько у меня цветов, если все из них, кроме двух, — розы, все, кроме двух, — тюльпаны, и все, кроме двух, — маргаритки?', '3 цветка (1 роза, 1 тюльпан, 1 маргаритка).', '', ''),
    (1, 18, 'Ученик собирался на вечер, когда погас свет в комнате, где в ящике шкафа лежали его коричневые и синие носки. Какое наименьшее число носков он должен взять из ящика, чтобы обеспечить себя парой одного цвета?', '3 носка.', 'Из трех носков как минимум два окажутся одного цвета (правый и левый носки не различаются).', ''),
    (1, 19, 'Бабушка жарит очень вкусные картофельные лепешки, пользуясь специальной сковородкой. Эта сковородка так мала, что одновременно на ней можно выпекать не более двух лепешек. Каждую из лепешек необходимо выпекать в течение одной минуты с каждой стороны. Какое минимальное время потребуется бабушке, чтобы приготовить: б) три лепешки?', '3 минуты.', '1-я мин: 1А+2А; 2-я мин: 1Б+3А; 3-я мин: 2Б+3Б.', ''),
    (1, 20, 'В банку попал 1 микроб, и через 35 минут банка была наполнена микробами, причем известно, что количество микробов ежеминутно удваивалось. За сколько минут банка была наполнена микробами наполовину?', 'За 34 минуты.', 'За последнюю (35-ю) минуту число микробов удвоилось с половины банки до полной.', ''),
    (2, 1, 'Продолжите последовательность, записав два следующих числа:
в) 6, 9, 18, 21, 42, 45, ...', '90, 93.', 'Поочередно выполняются операции «прибавить 3» и «умножить на 2» (45 × 2 = 90; 90 + 3 = 93).', '2 б.: Верно ровно 1 число на своей позиции (90 первым ИЛИ 93 вторым)
0 б.: 0 совпадений'),
    (2, 2, 'Проследите, как изменяются числа в каждом ряду, и продолжите каждый из рядов, вписав еще 4 числа.
о) 0, 3, 8, 15, 24, 35, ...', '48, 63, 80, 99.', 'Разности между соседними числами растут на 2 (+3, +5, +7, +9, +11, +13, +15, +17, +19) либо формула n² − 1: 7²−1=48, 8²−1=63, 9²−1=80, 10²−1=99.', '2 б.: Верны 2 или 3 числа из 4 на своих позициях
0 б.: 0–1 совпадение'),
    (2, 3, 'На затонувшей старинной каравелле были найдены шесть мешков с золотыми монетами. В первых четырех мешках оказалось соответственно 60, 30, 20 и 15 золотых монет. Когда подсчитали монеты в оставшихся двух мешках, кто-то заметил, что число монет в мешках подчиняется некой закономерности. Приняв это к сведению, смогли бы вы сказать, сколько монет в пятом и шестом мешках?', '12 и 10 монет.', 'Каждый следующий мешок содержит определенную часть от первого: 60 (1), 30 (1/2), 20 (1/3), 15 (1/4), 12 (1/5), 10 (1/6).', '2 б.: Верно ровно 1 число на своей позиции (12 для 5-го ИЛИ 10 для 6-го)
0 б.: 0 совпадений'),
    (2, 4, '«Двойные» ряды. Выявите закономерность и продолжите ряд, выписав еще не менее четырех его членов.
а) 1, 10, 3, 9, 5, 8, 7, 7, 9, 6, ...', '11, 5, 13, 4.', 'В ряду чередуются две последовательности: нечетные числа (1, 3, 5, 7, 9, 11, 13...) и убывающие от 10 (10, 9, 8, 7, 6, 5, 4...).', '2 б.: Верны 2 или 3 числа из первых четырех на своих позициях
0 б.: 0–1 совпадение'),
    (2, 5, 'В полдень на детскую площадку пришел Вася, через два часа после него — Маша, а через полтора часа после нее — Никита. Вася играл четыре часа, Маша — три часа, а Никита — два часа. Как долго Маша и Никита были на площадке вдвоем и в какое время?', '1 час, с 16:00 до 17:00.', 'Вася был с 12:00 до 16:00; Маша — с 14:00 до 17:00; Никита — с 15:30 до 17:30. Вдвоем (без Васи) Маша и Никита были 1 час, с 16:00 до 17:00.', '2 б.: Верен 1 параметр (1 час ИЛИ 16:00–17:00), ЛИБО «1,5 ч; 15:30–17:00»
0 б.: Иной ответ'),
    (2, 6, 'Юля веселее Аси, Ася легче Сони, Соня сильнее Юли, Юля тяжелее Сони, Соня печальнее Аси, Ася слабее Юли. Какая девочка самая веселая? Самая легкая? Самая сильная?', 'Самая веселая — Юля; самая легкая — Ася; самая сильная — Соня.', 'Веселее: Юля > Ася > Соня; легче: Ася < Соня < Юля; сильнее: Соня > Юля > Ася.', '2 б.: Верны ровно 2 ответа из 3
0 б.: 0–1 верный'),
    (2, 7, 'Возле школы растут шесть деревьев: сосна, береза, липа, тополь, ель и клен. Какое из этих деревьев самое высокое и какое — самое низкое, если известно, что береза ниже тополя, а липа выше клена, сосна ниже ели, липа ниже березы, сосна выше тополя?', 'Ель — самая высокая, клен — самый низкий.', 'Цепочка по убыванию высоты: ель > сосна > тополь > береза > липа > клен.', '2 б.: Верно ровно 1 дерево на своей позиции (ель ИЛИ клен)
0 б.: 0 совпадений'),
    (2, 8, 'В очереди за билетами в кино стоят Юра, Миша, Володя, Саша и Олег. Известно что:
1) Юра купит билет раньше Миши, но позже Олега;
2) Володя и Олег не стоят рядом;
3) Саша не находится рядом ни с Олегом, ни с Юрой, ни с Володей.
Кто за кем стоит?', '1 — Олег, 2 — Юра, 3 — Володя, 4 — Миша, 5 — Саша.', 'Из (1): Олег — Юра — Миша. Из (3): Саша стоит рядом только с Мишей (последним). Из (2): Володя не рядом с Олегом и не рядом с Сашей, значит между Юрой и Мишей.', '2 б.: Верно указаны 3 или 4 точных места из 5
0 б.: 0–2 места'),
    (2, 9, 'В ящике содержится 24 кг гвоздей. Как на чашечных весах без гирь отвесить ровно 21 кг гвоздей?', '1) 24 → 12 и 12 кг; 2) 12 → 6 и 6 кг; 3) 6 → 3 и 3 кг; итог: 12 + 6 + 3 = 21 кг (или 24 − 3 = 21 кг).', 'Делим 24 кг пополам (по 12 кг), 12 кг откладываем; вторые 12 кг делим пополам (по 6 кг), добавляем 6 кг к 12 кг; оставшиеся 6 кг делим пополам (по 3 кг), добавляем 3 кг к 18 кг: 12 + 6 + 3 = 21 кг.', '2 б.: Верны 2 деления (12 и 6) ИЛИ 3 деления без финального сбора 21 кг
0 б.: < 2 делений'),
    (2, 10, 'Кот Матроскин и пес Шарик нашли клад, который состоял из 9 одинаковых монет. В коробке, в которой лежали монеты, друзья обнаружили записку: «При помощи чашечных весов без гирь найдите среди этих 9 монет одну золотую и купите почтальону Печкину велосипед. Сделайте это при помощи двух взвешиваний. Золотая монета более тяжелая». Дядя Федор помог своим друзьям справиться с этим заданием. Как он действовал?', '1-е взвешивание: 3 против 3 (3 в стороне) → находим тяжелую тройку; 2-е взвешивание: 1 против 1 из этой тройки.', 'Раскладываем на 3 кучки: 3+3+3. Сравниваем две кучки: если равны — золотая в третьей, иначе — в более тяжелой. Во втором взвешивании сравниваем 2 монеты из найденной тройки.', '2 б.: Верно только 1-е (3 vs 3) ИЛИ рабочий способ за 3 взвешивания (4 vs 4)
0 б.: Нерабочий'),
    (2, 11, 'Этот случай вполне мог иметь место во времена «золотой лихорадки». На одном из приисков старатели были возмущены действиями Джо Макдоналда — хозяина салуна, принимавшего от них в уплату золотой песок. Очень уж необычными были гири, с помощью которых тот взвешивал золото: 1, 2, 4, 8, 16, 32 и 64 грамма. Джо утверждал, что с помощью такого набора гирь он может взвесить любую порцию золотого песка, не превышающую 100 граммов. Прав ли Джо Макдоналд? Какой наибольший вес можно измерить с помощью таких гирь? Как с помощью названных гирь набрать вес: а) 24 г; б) 49 г; в) 71 г; г) 106 г?', '1) Прав; 2) 127 г; 3) а) 16 + 8; 4) б) 32 + 16 + 1; 5) в) 64 + 4 + 2 + 1; 6) г) 64 + 32 + 8 + 2.', 'Сумма всех гирь: 1+2+4+8+16+32+64 = 127 г (поэтому Джо прав). Разложения единственны: 24=16+8; 49=32+16+1; 71=64+4+2+1; 106=64+32+8+2.', '2 б.: Верно выполнены 3, 4 или 5 пунктов из 6
0 б.: 0–2 пункта'),
    (2, 12, 'Катя, Соня, Галя и Тамара родились 2 марта, 17 мая, 2 июля и 20 марта. Соня и Галя родились в одном месяце, а дни рождения Гали и Кати обозначаются одинаковыми числами. Назовите дату рождения каждой девочки.', 'Галя — 2 марта, Соня — 20 марта, Катя — 2 июля, Тамара — 17 мая.', 'В марте две даты (2 и 20 марта) — это Соня и Галя. Число 2 совпадает с 2 июля — значит Галя родилась 2 марта, Катя — 2 июля, Соня — 20 марта, Тамара — 17 мая.', '2 б.: Верно определены 2 или 3 девочки из 4
0 б.: 0–1 пара'),
    (2, 13, 'Каждый из 35 пятиклассников является читателем по крайней мере одной из двух библиотек: школьной и районной. Из них 25 учащихся берут книги в школьной библиотеке, 20 — в районной. Сколько из пятиклассников:
а) не являются читателями школьной библиотеки;
б) не являются читателями районной библиотеки;
в) являются читателями только школьной библиотеки;
г) являются читателями только районной библиотеки;
д) являются читателями обеих библиотек?', 'а) 10; б) 15; в) 15; г) 10; д) 10.', 'а) 35−25=10; б) 35−20=15; д) 25+20−35=10 (читатели обеих); в) 25−10=15 (только школьной); г) 20−10=10 (только районной).', '2 б.: Верны 3 или 4 числа из 5 на своих буквах (а–д)
0 б.: 0–2 числа'),
    (2, 14, 'Ваня, Петя, Саша и Коля носят фамилии, начинающиеся на буквы В, П, С и К. Известно, что:
1) Ваня и С. — отличники;
2) Петя и В. — троечники;
3) В. ростом выше П.;
4) Коля ростом ниже П.;
5) у Саши и Пети одинаковый рост.
На какую букву начинается фамилия каждого мальчика?', 'Ваня — П., Петя — К., Саша — В., Коля — С.', 'Из (1) и (2): Ваня и С. отличники, Петя и В. троечники → Ваня не С. и не В.; Петя не В. и не С. Из (3)–(5): рост В. > П. > Коли, а Саша = Петя → В. выше Коли, значит В. = Саша. Тогда Петя не В., не С. и не П. (рост Саши=Пети=В. > П.), значит Петя — К., Ваня — П., Коля — С.', '2 б.: Верно определены 2 или 3 мальчика из 4
0 б.: 0–1 пара'),
    (2, 15, 'В семье четверо детей: им 5, 8, 13 и 15 лет. Зовут их Таня, Юра, Света и Лена. Сколько лет каждому из них, если одна девочка ходит в детский сад, Таня старше, чем Юра, а сумма лет Тани и Светы делится на 3?', 'Свете 5 лет, Юре 8 лет, Тане 13 лет, Лене 15 лет.', '5 лет — девочке (не Юре). Юра младше Тани, значит ему не 15. На 3 делятся только суммы 5+13=18 и 8+13=21, значит 13 лет — Тане или Свете, следовательно Юре 8 лет. Так как Таня старше Юры, Тане 13, Свете 5, Лене 15.', '2 б.: Верно определены 2 или 3 ребенка из 4
0 б.: 0–1 пара'),
    (3, 1, 'Туристы (отец, мать и два брата-близнеца) должны переправиться через реку. В их распоряжении есть маленькая лодка, вмещающая только одного взрослого или двоих детей. Как организовать самую скорую переправу, если и взрослые, и дети умеют грести? Сколько времени потребуется на переправу, если каждая поездка через реку (в одну сторону) занимает 10 минут?', '1 час 30 минут (90 минут, 9 рейсов).', 'Алгоритм: 1) два сына →; 2) один сын ←; 3) отец →; 4) второй сын ←; 5) два сына →; 6) один сын ←; 7) мать →; 8) второй сын ←; 9) два сына →. Итого 9 × 10 = 90 минут.', ''),
    (3, 2, 'Как отмерить 15 минут, необходимых для варки каши, при помощи песочных часов, отмеряющих 7 минут и 11 минут?', 'Запустить оба таймера одновременно; начать варку по окончании 7-минутных; когда кончатся 11-минутные (4 мин), перевернуть 11-минутные еще раз (4 + 11 = 15 мин).', 'Также засчитывать верный альтернативный способ: начать варку сразу с запуском обоих часов; на 7-й минуте перевернуть 7-минутные; на 11-й минуте (когда в 7-минутных высыпалось 4 мин) снова перевернуть их — высыпятся 4 мин (11 + 4 = 15 мин).', ''),
    (3, 3, 'Глория больше всего любит желтый и розовый цвета. В ящике для перчаток у Глории лежат шесть пар желтых и шесть пар розовых перчаток. Они перемешаны в беспорядке. Сколько перчаток Глория должна вытащить из ящика, чтобы среди них наверняка оказалась пара одного цвета? Глории все равно, какого цвета окажется эта пара — желтого или розового.', '13 перчаток.', 'Перчатки бывают левые и правые. В худшем случае сначала попадутся все 12 левых (6 желтых и 6 розовых). 13-я перчатка обязательно окажется правой и составит пару с одной из уже вытащенных.', ''),
    (3, 4, 'В магазине было шесть разных ящиков с гвоздями, массы ящиков 6, 7, 8, 9, 10, 11 кг. Пять из них приобрели два покупателя, причем каждому из них гвоздей досталось поровну. Какой ящик остался в магазине?', '4-й ящик (массой 9 кг).', 'Общая масса 51 кг (нечетна), значит оставшийся ящик имеет нечетную массу (7, 9 или 11). При 7 кг остаток 44 (22 кг не набрать); при 11 кг остаток 40 (20 кг не набрать); при 9 кг остаток 42: 10+11 = 6+7+8 = 21 кг.', ''),
    (3, 5, 'В некотором царстве-государстве повадился Змей Горыныч разбойничать. Послал царь четырех богатырей погубить Змея, а награду за то обещал великую. Вернулись богатыри с победой, и спрашивает их царь: «Так кто же из вас главный победитель, кому достанется царева дочь и полцарства?» Засмущались добры молодцы и ответы дали туманные.
1) Илья Муромец сказал: «Это все Алеша Попович, царь-батюшка».
2) Алеша Попович возразил: «То был Микула Селянинович».
3) Микула Селянинович: «Не прав Алеша, не я это».
4) Добрыня Никитич: «И не я, батюшка».
Подвернулась тут Баба-Яга и говорит царю: «А прав-то лишь один из богатырей, видела я всю битву своими глазами». Кто же из богатырей победил Змея Горыныча?', 'Добрыня Никитич.', 'Высказывания (2) и (3) противоречат друг другу, значит одно из них истинно, а (1) и (4) ложны. Из ложности (4) следует, что победил Добрыня Никитич (истинно высказывание Микулы Селяниновича).', ''),
    (3, 6, 'Алеша, Боря и Гриша нашли в земле старинный сосуд. Рассматривая удивительную находку, каждый высказал по два предположения.
1) Алеша: «Это сосуд греческий и изготовлен в V веке».
2) Боря: «Это сосуд финикийский и изготовлен в III веке».
3) Гриша: «Это сосуд не греческий и изготовлен в IV веке».
Учитель истории сказал ребятам, что каждый из них прав только в одном из двух предположений. Где и в каком веке изготовлен сосуд?', 'Сосуд финикийский, изготовлен в V веке.', 'Если бы сосуд был греческим, то у Гриши верным было бы «IV век», и тогда оба предположения Бори («финикийский» и «III век») оказались бы ложны — противоречие. Значит сосуд не греческий (финикийский), а из слов Алеши следует V век.', ''),
    (3, 7, 'В автомашине пять мест. Сколькими способами пять человек могут усесться в эту машину, если занять место водителя могут только двое из них?', '48 способов.', 'На место водителя 2 варианта, на остальные четыре места — 4×3×2×1 = 24 варианта. Всего 2 × 4 × 3 × 2 × 1 = 48.', ''),
    (3, 8, 'Сколько трехзначных чисел можно составить из цифр 1, 2, 4, 6, если никакую цифру не использовать более одного раза? Сколько среди этих чисел будет четных? Сколько нечетных?', 'Всего 24 числа; из них 18 четных и 6 нечетных.', 'Всего 4 × 3 × 2 = 24 числа. Нечетными будут те, что оканчиваются на 1 (1/4 всех чисел): 3 × 2 × 1 = 6 нечетных чисел; четных: 24 − 6 = 18.', ''),
    (3, 9, 'Даны предложения на русском языке. В правом столбце дан перевод слов каждого предложения на язык туземцев (слова даны в произвольном порядке). Составьте фрагмент русско-туземского словаря по этому переводу.
Мышка ночью пошла гулять — Ам, ту, му, ям
Кошка ночью видит мышка — Ту, ля, бу, ам
Мышку кошка пошла поймать — Гу, ля, ту, ям', 'Мышка — ту, пошла — ям, гулять — му, ночью — ам, кошка — ля, видит — бу, поймать — гу.', '«Мышка» есть во всех трех фразах → ту; «ночью» в 1-й и 2-й → ам; «пошла» в 1-й и 3-й → ям; «кошка» во 2-й и 3-й → ля. Остаются: гулять — му, видит — бу, поймать — гу.', ''),
    (3, 10, 'Для шифровки букв используются двузначные числа. Известно, что каждое из слов «марс», «пирс», «барс» и «морс» кодируется одной из последовательностей двузначных чисел: 87 62 90 93; 10 05 90 93; 80 84 90 93; 80 05 90 93. Какая последовательность двузначных чисел является кодом слова «сироп»?', '93 62 90 84 87.', 'Во всех словах «рс» = 90 93. Буква «м» первая в двух словах → м=80; буква «а» вторая в двух словах → а=05. Значит «марс»=80 05 90 93, «морс»=80 84 90 93 (о=84), «барс»=10 05 90 93, «пирс»=87 62 90 93 (п=87, и=62). Код «сироп»: 93 62 90 84 87.', ''),
    (4, 1, 'В результате ошибок служителей зоопарка звери оказались не в своих клетках: 1. Лев (пантера), 2. Осел (крокодил), 3. Волк (осел), 4. Крокодил (лев), 5. Пантера (волк). Работнику зоопарка необходимо как можно быстрее разместить животных по их клеткам. Каким должен быть алгоритм действий этого работника? Поскольку все звери, кроме осла, хищники, их нельзя помещать вдвоем в одну клетку или выпускать вдвоем в общий вольер, в который открываются клетки.', '6 перемещений.', 'Вариант 1: 1) волк → общий вольер; 2) пантера → кл. 5; 3) лев → кл. 1; 4) крокодил → кл. 4; 5) осел → кл. 2; 6) волк → кл. 3. (Или начать с вывода осла в вольер.)', ''),
    (4, 2, 'Взять 15 шашек и провести с товарищем следующую игру: каждый из двух играющих по очереди берет шашки; за один раз можно брать одну, две или три шашки; проигрывает тот, кто берет последнюю шашку. Рассчитать, сколько шашек должен брать каждый раз первый игрок, чтобы всегда выигрывать.', 'Первый игрок должен взять сначала 2 шашки (оставить 13), а затем дополнять ход соперника до 4, оставляя 9, 5 и 1 шашку.', '', ''),
    (4, 3, 'У одного путешественника не было денег, но была золотая цепочка из семи звеньев. Хозяин гостиницы, к которому обратился путешественник с просьбой о ночлеге, согласился держать постояльца и установил плату: одно звено цепочки за одни сутки проживания. Какое одно звено достаточно распилить, чтобы путешественник мог остановиться в гостинице на любой срок в пределах от 1 до 7 суток?', 'Третье звено (образуются части в 1, 2 и 4 звена, ими можно расплатиться за 1..7 суток со сдачей).', '', '')
) AS v(round, question_number, text, answer, explanation, criteria)
WHERE e.name = 'Третий региональный математический турнир школьных команд «Королевская битва»'
ON CONFLICT (event_id, round, question_number) DO UPDATE SET
    text = EXCLUDED.text,
    answer = EXCLUDED.answer,
    explanation = EXCLUDED.explanation,
    criteria = EXCLUDED.criteria;
-- +goose StatementEnd

-- +goose Down
-- +goose StatementBegin
DELETE FROM quiz_questions
WHERE event_id IN (SELECT id FROM events WHERE name = 'Третий региональный математический турнир школьных команд «Королевская битва»');
-- +goose StatementEnd
